B.Ho=new A.bO("\u0627\u0644\u062c\u064a\u0632\u0629","\u0625\u062c\u0645\u0627\u0644\u064a \u0639\u062f\u062f \u0627\u0644\u0645\u0634\u0631\u0648\u0639\u0627\u062a \u0627\u0644\u062a\u0646\u0645\u0648\u064a\u0629: 550 \u0645\u0634\u0631\u0648\u0639\u0627\u064b \u062a\u0646\u0645\u0648\u064a\u0627\u064b.","\u0625\u062c\u0645\u0627\u0644\u064a \u0627\u0644\u0627\u0633\u062a\u062b\u0645\u0627\u0631\u0627\u062a \u0627\u0644\u0639\u0627\u0645\u0629: \u0646\u062d\u0648 93.5 \u0645\u0644\u064a\u0627\u0631 \u062c\u0646\u064a\u0647.\n\u0627\u0644\u0646\u0642\u0644 \u0648\u0627\u0644\u0645\u0648\u0627\u0635\u0644\u0627\u062a: 53% \u0628\u0642\u064a\u0645\u0629 \u062a\u0642\u0627\u0631\u0628 49.4 \u0645\u0644\u064a\u0627\u0631 \u062c\u0646\u064a\u0647.\n\u0627\u0644\u0625\u0633\u0643\u0627\u0646 \u0648\u0645\u064a\u0627\u0647 \u0627\u0644\u0634\u0631\u0628 \u0648\u0627\u0644\u0635\u0631\u0641 \u0627\u0644\u0635\u062d\u064a: 32% \u0628\u0642\u064a\u0645\u0629 30 \u0645\u0644\u064a\u0627\u0631 \u062c\u0646\u064a\u0647.\n\u0627\u0644\u062a\u0646\u0645\u064a\u0629 \u0627\u0644\u0645\u062d\u0644\u064a\u0629: 3.9 \u0645\u0644\u064a\u0627\u0631 \u062c\u0646\u064a\u0647.\n\u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u0639\u0627\u0644\u064a: 3.2 \u0645\u0644\u064a\u0627\u0631 \u062c\u0646\u064a\u0647.\n\u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0642\u0628\u0644 \u0627\u0644\u062c\u0627\u0645\u0639\u064a: 1.4 \u0645\u0644\u064a\u0627\u0631 \u062c\u0646\u064a\u0647.\n\u0627\u0644\u0635\u062d\u0629: 936 \u0645\u0644\u064a\u0648\u0646 \u062c\u0646\u064a\u0647.","\u0627\u0644\u0646\u0642\u0644 \u0648\u0627\u0644\u0645\u0648\u0627\u0635\u0644\u0627\u062a\u060c \u0627\u0644\u0625\u0633\u0643\u0627\u0646 \u0648\u0627\u0644\u0645\u0631\u0627\u0641\u0642\u060c \u0627\u0644\u062a\u0646\u0645\u064a\u0629 \u0627\u0644\u0645\u062d\u0644\u064a\u0629\u060c \u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u0639\u0627\u0644\u064a\u060c \u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0642\u0628\u0644 \u0627\u0644\u062c\u0627\u0645\u0639\u064a\u060c \u0627\u0644\u0635\u062d\u0629\u060c \u0627\u0644\u0628\u0646\u064a\u0629 \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629 \u0648\u0627\u0644\u062e\u062f\u0645\u0627\u062a.","\u062a\u0637\u0648\u064a\u0631 \u0627\u0644\u0645\u0646\u0637\u0642\u0629 \u0627\u0644\u0635\u0646\u0627\u0639\u064a\u0629 \u0628\u0623\u0628\u0648 \u0631\u0648\u0627\u0634.\n\n\u062a\u0637\u0648\u064a\u0631 \u0645\u062d\u064a\u0637 \u0627\u0644\u0645\u062a\u062d\u0641 \u0627\u0644\u0645\u0635\u0631\u064a \u0627\u0644\u0643\u0628\u064a\u0631 \u0648\u0634\u0628\u0643\u0629 \u0627\u0644\u0637\u0631\u0642 \u0627\u0644\u0645\u062d\u064a\u0637\u0629 \u0628\u0647.\n\n\u0631\u0635\u0641 \u0648\u062a\u0637\u0648\u064a\u0631 \u0634\u0628\u0643\u0629 \u0627\u0644\u0637\u0631\u0642 \u0627\u0644\u0645\u062d\u0644\u064a\u0629.\n\n\u062a\u062d\u0633\u064a\u0646 \u0645\u0646\u0638\u0648\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631 \u0648\u0627\u0644\u0628\u064a\u0626\u0629 \u0648\u0625\u062f\u0627\u0631\u0629 \u0627\u0644\u0645\u062e\u0644\u0641\u0627\u062a \u0627\u0644\u0635\u0644\u0628\u0629.\n\n\u0645\u0628\u0627\u062f\u0631\u0629 \u062d\u064a\u0627\u0629 \u0643\u0631\u064a\u0645\u0629 \u0641\u064a \u0645\u0631\u0643\u0632\u064a \u0627\u0644\u0635\u0641 \u0648\u0623\u0637\u0641\u064a\u062d\u060c \u0648\u062a\u0633\u062a\u0647\u062f\u0641 \u0627\u0644\u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u0623\u0648\u0644\u0649 42 \u0642\u0631\u064a\u0629 \u0644\u062e\u062f\u0645\u0629 \u0623\u0643\u062b\u0631 \u0645\u0646 801 \u0623\u0644\u0641 \u0646\u0633\u0645\u0629.","\u0645\u062d\u0627\u0641\u0638\u0629 \u0631\u0626\u064a\u0633\u064a\u0629 \u0641\u064a \u0625\u0642\u0644\u064a\u0645 \u0627\u0644\u0642\u0627\u0647\u0631\u0629 \u0627\u0644\u0643\u0628\u0631\u0649 \u0648\u062a\u0636\u0645 \u0645\u0646\u0627\u0637\u0642 \u062d\u0636\u0631\u064a\u0629 \u0648\u0631\u064a\u0641\u064a\u0629 \u0648\u0645\u0634\u0631\u0648\u0639\u0627\u062a \u0642\u0648\u0645\u064a\u0629 \u0643\u0628\u0631\u0649.",u.X)
B.HC=new A.bO("\u0627\u0644\u0642\u0644\u064a\u0648\u0628\u064a\u0629","\u0627\u0644\u062e\u0637\u0629 \u0627\u0644\u0627\u0633\u062a\u062b\u0645\u0627\u0631\u064a\u0629 \u062a\u0636\u0645 \u0646\u062d\u0648 367 \u0645\u0634\u0631\u0648\u0639\u0627\u064b \u062a\u0646\u0645\u0648\u064a\u0627\u064b \u0641\u0631\u0639\u064a\u0627\u064b\u060c \u0628\u0627\u0644\u0625\u0636\u0627\u0641\u0629 \u0625\u0644\u0649 703 \u0645\u0634\u0631\u0648\u0639\u0627\u062a \u0636\u0645\u0646 \u0645\u0628\u0627\u062f\u0631\u0629 \u062d\u064a\u0627\u0629 \u0643\u0631\u064a\u0645\u0629 \u0628\u0645\u0631\u0643\u0632 \u0634\u0628\u064a\u0646 \u0627\u0644\u0642\u0646\u0627\u0637\u0631.","\u0627\u0644\u0625\u0633\u0643\u0627\u0646 \u0648\u0627\u0644\u0645\u0631\u0627\u0641\u0642: \u0627\u0644\u0646\u0633\u0628\u0629 \u0627\u0644\u0623\u0643\u0628\u0631 \u0648\u062a\u0642\u062a\u0631\u0628 \u0645\u0646 55%.\n\u0627\u0644\u062a\u0646\u0645\u064a\u0629 \u0627\u0644\u0645\u062d\u0644\u064a\u0629 \u0648\u0627\u0644\u062e\u062f\u0645\u0627\u062a: 11%.\n\u0627\u0644\u0637\u0631\u0642 \u0648\u0627\u0644\u0646\u0642\u0644 \u0627\u0644\u0645\u062d\u0644\u064a.\n\u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u0639\u0627\u0644\u064a \u0648\u0642\u0628\u0644 \u0627\u0644\u062c\u0627\u0645\u0639\u064a.\n\u0627\u0644\u0635\u062d\u0629.","\u0627\u0644\u0625\u0633\u0643\u0627\u0646 \u0648\u0627\u0644\u0645\u0631\u0627\u0641\u0642\u060c \u0627\u0644\u062a\u0646\u0645\u064a\u0629 \u0627\u0644\u0645\u062d\u0644\u064a\u0629\u060c \u0627\u0644\u0637\u0631\u0642 \u0648\u0627\u0644\u0646\u0642\u0644\u060c \u0627\u0644\u062a\u0639\u0644\u064a\u0645\u060c \u0627\u0644\u0635\u062d\u0629\u060c \u062a\u062d\u0633\u064a\u0646 \u0627\u0644\u0628\u064a\u0626\u0629\u060c \u0627\u0644\u0643\u0647\u0631\u0628\u0627\u0621 \u0648\u0627\u0644\u0625\u0646\u0627\u0631\u0629.","\u062a\u0645 \u0627\u0644\u0627\u0646\u062a\u0647\u0627\u0621 \u0645\u0646 702 \u0645\u0634\u0631\u0648\u0639 \u0645\u0646 \u0625\u062c\u0645\u0627\u0644\u064a 703 \u0645\u0634\u0631\u0648\u0639\u0627\u062a \u0628\u062d\u064a\u0627\u0629 \u0643\u0631\u064a\u0645\u0629 \u0641\u064a \u0634\u0628\u064a\u0646 \u0627\u0644\u0642\u0646\u0627\u0637\u0631.\n\n\u0625\u0646\u0647\u0627\u0621 \u0648\u062a\u0648\u0633\u064a\u0639 25 \u0645\u0634\u0631\u0648\u0639\u0627\u064b \u0644\u0645\u064a\u0627\u0647 \u0627\u0644\u0634\u0631\u0628\u060c \u0648\u0645\u0646 \u0628\u064a\u0646\u0647\u0627 \u0645\u062d\u0637\u0629 \u0645\u064a\u0627\u0647 \u0637\u0648\u062e.\n\n\u0625\u062d\u0644\u0627\u0644 \u0648\u062a\u0648\u0633\u0639\u0629 28 \u0645\u062f\u0631\u0633\u0629 \u0648\u062a\u0648\u0641\u064a\u0631 573 \u0641\u0635\u0644\u0627\u064b \u062c\u062f\u064a\u062f\u0627\u064b.\n\n\u062a\u062d\u062f\u064a\u062b \u0627\u0644\u0645\u062e\u0637\u0637\u0627\u062a \u0627\u0644\u062a\u0641\u0635\u064a\u0644\u064a\u0629 \u0641\u064a \u0628\u0646\u0647\u0627 \u0648\u0642\u0647\u0627 \u0648\u0627\u0644\u0642\u0646\u0627\u0637\u0631 \u0627\u0644\u062e\u064a\u0631\u064a\u0629 \u0648\u063a\u0631\u0628 \u0634\u0628\u0631\u0627 \u0627\u0644\u062e\u064a\u0645\u0629.\n\n\u0631\u0635\u0641 \u0627\u0644\u0637\u0631\u0642 \u0648\u062a\u0631\u0643\u064a\u0628 \u0627\u0644\u0625\u0646\u062a\u0631\u0644\u0648\u0643 \u0648\u062a\u0637\u0648\u064a\u0631 \u0627\u0644\u0623\u0633\u0648\u0627\u0642 \u0648\u0627\u0644\u0645\u0648\u0627\u0642\u0641 \u0627\u0644\u0646\u0645\u0648\u0630\u062c\u064a\u0629.","\u0645\u062d\u0627\u0641\u0638\u0629 \u0643\u062b\u064a\u0641\u0629 \u0627\u0644\u0633\u0643\u0627\u0646 \u0636\u0645\u0646 \u0625\u0642\u0644\u064a\u0645 \u0627\u0644\u0642\u0627\u0647\u0631\u0629 \u0627\u0644\u0643\u0628\u0631\u0649 \u0648\u062a\u0636\u0645 \u0639\u062f\u062f\u0627\u064b \u0643\u0628\u064a\u0631\u0627\u064b \u0645\u0646 \u0627\u0644\u0645\u0634\u0631\u0648\u0639\u0627\u062a \u0627\u0644\u062e\u062f\u0645\u064a\u0629.",u.X)
B.Hu=new A.bO("\u0627\u0644\u0625\u0633\u0643\u0646\u062f\u0631\u064a\u0629","\u062a\u0634\u062a\u0645\u0644 \u0627\u0644\u062e\u0637\u0629 \u0627\u0644\u062a\u0646\u0645\u0648\u064a\u0629 \u0639\u0644\u0649 548 \u0645\u0634\u0631\u0648\u0639\u0627\u064b \u062a\u0646\u0645\u0648\u064a\u0627\u064b \u0645\u0648\u0632\u0639\u0629 \u0639\u0644\u0649 \u0627\u0644\u0623\u062d\u064a\u0627\u0621 \u0648\u0627\u0644\u0645\u0631\u0627\u0643\u0632.","\u0627\u0644\u0646\u0642\u0644 \u0648\u0627\u0644\u0645\u0648\u0627\u0635\u0644\u0627\u062a: 42.5 \u0645\u0644\u064a\u0627\u0631 \u062c\u0646\u064a\u0647 \u0628\u0646\u0633\u0628\u0629 67%.\n\u0627\u0644\u0625\u0633\u0643\u0627\u0646 \u0648\u0627\u0644\u0645\u0631\u0627\u0641\u0642: 7.4 \u0645\u0644\u064a\u0627\u0631 \u062c\u0646\u064a\u0647 \u0628\u0646\u0633\u0628\u0629 11.5%.\n\u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u0639\u0627\u0644\u064a: 4.2 \u0645\u0644\u064a\u0627\u0631 \u062c\u0646\u064a\u0647 \u0628\u0646\u0633\u0628\u0629 7%.\n\u0627\u0644\u062a\u0646\u0645\u064a\u0629 \u0627\u0644\u0645\u062d\u0644\u064a\u0629: 2.5 \u0645\u0644\u064a\u0627\u0631 \u062c\u0646\u064a\u0647 \u0628\u0646\u0633\u0628\u0629 4%.\n\u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0642\u0628\u0644 \u0627\u0644\u062c\u0627\u0645\u0639\u064a: 527 \u0645\u0644\u064a\u0648\u0646 \u062c\u0646\u064a\u0647.\n\u0627\u0644\u0635\u062d\u0629: 429 \u0645\u0644\u064a\u0648\u0646 \u062c\u0646\u064a\u0647.\n\u0642\u0637\u0627\u0639\u0627\u062a \u0623\u062e\u0631\u0649: 8.4 \u0645\u0644\u064a\u0627\u0631 \u062c\u0646\u064a\u0647.","\u0627\u0644\u0646\u0642\u0644 \u0648\u0627\u0644\u0645\u0648\u0627\u0635\u0644\u0627\u062a\u060c \u0627\u0644\u0625\u0633\u0643\u0627\u0646 \u0648\u0627\u0644\u0645\u0631\u0627\u0641\u0642\u060c \u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u0639\u0627\u0644\u064a\u060c \u0627\u0644\u062a\u0646\u0645\u064a\u0629 \u0627\u0644\u0645\u062d\u0644\u064a\u0629\u060c \u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0642\u0628\u0644 \u0627\u0644\u062c\u0627\u0645\u0639\u064a\u060c \u0627\u0644\u0635\u062d\u0629\u060c \u0627\u0644\u062e\u062f\u0645\u0627\u062a.","\u062a\u0637\u0648\u064a\u0631 \u0634\u0627\u0645\u0644 \u0644\u0645\u062a\u0631\u0648 \u0623\u0628\u0648 \u0642\u064a\u0631.\n\n\u062a\u0648\u0633\u0639\u0629 \u0637\u0631\u064a\u0642 \u0627\u0644\u0643\u0648\u0631\u0646\u064a\u0634 \u0628\u0637\u0648\u0644 4.4 \u0643\u0645.\n\n\u0645\u062f\u064a\u0646\u0629 \u0623\u0628\u0648 \u0642\u064a\u0631 \u0627\u0644\u062c\u062f\u064a\u062f\u0629 \u0639\u0644\u0649 \u0645\u0633\u0627\u062d\u0629 3,500 \u0641\u062f\u0627\u0646.\n\n\u0627\u0633\u062a\u0643\u0645\u0627\u0644 \u0645\u062d\u0648\u0631 \u0627\u0644\u0644\u0648\u0627\u0621 \u0639\u0645\u0631 \u0633\u0644\u064a\u0645\u0627\u0646.\n\n\u062a\u0648\u0633\u0639\u0627\u062a \u0645\u062d\u0637\u0629 \u0627\u0644\u0645\u0639\u0627\u0644\u062c\u0629 \u0627\u0644\u063a\u0631\u0628\u064a\u0629 \u0644\u0644\u0635\u0631\u0641 \u0627\u0644\u0635\u062d\u064a.\n\n\u062a\u0646\u0641\u064a\u0630 \u0627\u0644\u0645\u0633\u0627\u0631 \u0627\u0644\u0646\u0627\u0642\u0644 \u0644\u0645\u064a\u0627\u0647 \u062a\u0631\u0639\u0629 \u0627\u0644\u062d\u0645\u0627\u0645 \u0636\u0645\u0646 \u0645\u0634\u0631\u0648\u0639 \u0627\u0644\u062f\u0644\u062a\u0627 \u0627\u0644\u062c\u062f\u064a\u062f\u0629.\n\n\u0628\u0631\u0627\u0645\u062c \u0627\u0644\u0625\u0633\u0643\u0627\u0646 \u0648\u0625\u0646\u0634\u0627\u0621 \u0648\u0625\u062d\u0644\u0627\u0644 \u0627\u0644\u0645\u062f\u0627\u0631\u0633.","\u0645\u062d\u0627\u0641\u0638\u0629 \u0633\u0627\u062d\u0644\u064a\u0629 \u0643\u0628\u0631\u0649 \u0648\u0645\u0631\u0643\u0632 \u0627\u0642\u062a\u0635\u0627\u062f\u064a \u0648\u062a\u062c\u0627\u0631\u064a \u0648\u0635\u0646\u0627\u0639\u064a \u0645\u0647\u0645.",u.X)
B.HG=new A.bO("\u0627\u0644\u0628\u062d\u064a\u0631\u0629","\u0625\u062c\u0645\u0627\u0644\u064a \u0627\u0644\u0645\u0634\u0631\u0648\u0639\u0627\u062a \u0627\u0644\u062a\u0646\u0645\u0648\u064a\u0629 \u064a\u0628\u0644\u063a 422 \u0645\u0634\u0631\u0648\u0639\u0627\u064b \u0645\u0648\u0632\u0639\u0629 \u0639\u0644\u0649 \u0645\u0631\u0627\u0643\u0632 \u0648\u0642\u0631\u0649 \u0627\u0644\u0645\u062d\u0627\u0641\u0638\u0629.","\u0627\u0644\u0625\u0633\u0643\u0627\u0646: 22%.\n\u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u0639\u0627\u0644\u064a: 16%.\n\u0627\u0644\u0646\u0642\u0644: 16%.\n\u0627\u0644\u062a\u0646\u0645\u064a\u0629 \u0627\u0644\u0645\u062d\u0644\u064a\u0629: 14%.\n\u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0642\u0628\u0644 \u0627\u0644\u062c\u0627\u0645\u0639\u064a: 11%.\n\u0627\u0644\u0635\u062d\u0629: 11%.","\u0627\u0644\u0625\u0633\u0643\u0627\u0646 \u0648\u0627\u0644\u0645\u0631\u0627\u0641\u0642\u060c \u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u0639\u0627\u0644\u064a\u060c \u0627\u0644\u0646\u0642\u0644\u060c \u0627\u0644\u062a\u0646\u0645\u064a\u0629 \u0627\u0644\u0645\u062d\u0644\u064a\u0629\u060c \u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0642\u0628\u0644 \u0627\u0644\u062c\u0627\u0645\u0639\u064a\u060c \u0627\u0644\u0635\u062d\u0629.","\u0627\u0633\u062a\u0643\u0645\u0627\u0644 52 \u0645\u0634\u0631\u0648\u0639\u0627\u064b \u0641\u064a \u0645\u064a\u0627\u0647 \u0627\u0644\u0634\u0631\u0628 \u0648\u0627\u0644\u0635\u0631\u0641 \u0627\u0644\u0635\u062d\u064a.\n\n\u0627\u0633\u062a\u0643\u0645\u0627\u0644 \u062a\u0648\u0633\u0639\u0627\u062a \u0645\u062d\u0637\u0629 \u0635\u0631\u0641 \u0635\u062d\u064a \u0634\u0628\u0631\u0627\u062e\u064a\u062a.\n\n\u0627\u0633\u062a\u0643\u0645\u0627\u0644 \u0628\u0646\u0627\u0621 \u0648\u062a\u062c\u0647\u064a\u0632 7,830 \u0648\u062d\u062f\u0629 \u0633\u0643\u0646\u064a\u0629 \u0636\u0645\u0646 \u0645\u0628\u0627\u062f\u0631\u0629 \u0633\u0643\u0646 \u0644\u0643\u0644 \u0627\u0644\u0645\u0635\u0631\u064a\u064a\u0646.\n\n\u0627\u0633\u062a\u0643\u0645\u0627\u0644 \u0627\u0644\u0645\u062c\u0645\u0639 \u0627\u0644\u062d\u0631\u0641\u064a \u0628\u0641\u0631\u0647\u0627\u0634 \u0628\u062d\u0648\u0634 \u0639\u064a\u0633\u0649.\n\n\u0627\u0633\u062a\u0643\u0645\u0627\u0644 \u0627\u0644\u0645\u0633\u062a\u0634\u0641\u0649 \u0627\u0644\u062c\u0627\u0645\u0639\u064a \u0627\u0644\u062c\u062f\u064a\u062f \u0628\u0627\u0644\u0628\u062d\u064a\u0631\u0629 \u0628\u0637\u0627\u0642\u0629 273 \u0633\u0631\u064a\u0631\u0627\u064b.\n\n\u0645\u0634\u0631\u0648\u0639\u0627\u062a \u062d\u064a\u0627\u0629 \u0643\u0631\u064a\u0645\u0629 \u0641\u064a 6 \u0645\u0631\u0627\u0643\u0632 \u0631\u0626\u064a\u0633\u064a\u0629.","\u0645\u062d\u0627\u0641\u0638\u0629 \u0643\u0628\u064a\u0631\u0629 \u0641\u064a \u063a\u0631\u0628 \u0627\u0644\u062f\u0644\u062a\u0627 \u0648\u062a\u062a\u0645\u064a\u0632 \u0628\u0627\u0644\u0646\u0634\u0627\u0637 \u0627\u0644\u0632\u0631\u0627\u0639\u064a \u0648\u0627\u0645\u062a\u062f\u0627\u062f \u062c\u063a\u0631\u0627\u0641\u064a \u0648\u0627\u0633\u0639.",u.X)
B.HB=new A.bO("\u0645\u0637\u0631\u0648\u062d","\u064a\u0633\u062a\u0647\u062f\u0641 \u0627\u0644\u0645\u062e\u0637\u0637 \u062a\u0646\u0641\u064a\u0630 212 \u0645\u0634\u0631\u0648\u0639\u0627\u064b \u062a\u0646\u0645\u0648\u064a\u0627\u064b \u062a\u063a\u0637\u064a \u0627\u0644\u0642\u0637\u0627\u0639\u0627\u062a \u0627\u0644\u062e\u062f\u0645\u064a\u0629 \u0648\u0645\u0631\u0627\u0643\u0632 \u0627\u0644\u0645\u062d\u0627\u0641\u0638\u0629 \u0627\u0644\u062b\u0645\u0627\u0646\u064a\u0629.","\u0627\u0644\u0637\u0627\u0642\u0629 \u0648\u0627\u0644\u0643\u0647\u0631\u0628\u0627\u0621 \u0645\u0646 \u0627\u0644\u0642\u0637\u0627\u0639\u0627\u062a \u0627\u0644\u0631\u0626\u064a\u0633\u064a\u0629 \u0627\u0644\u0645\u0633\u062a\u0641\u064a\u062f\u0629.\n\u0627\u0644\u0646\u0642\u0644 \u0648\u0627\u0644\u0637\u0631\u0642 \u0644\u062a\u0637\u0648\u064a\u0631 \u0627\u0644\u0645\u062d\u0627\u0648\u0631 \u0627\u0644\u062f\u0648\u0644\u064a\u0629 \u0648\u0631\u0628\u0637 \u0627\u0644\u0645\u0631\u0627\u0643\u0632.\n\u0627\u0644\u0625\u0633\u0643\u0627\u0646 \u0648\u0645\u064a\u0627\u0647 \u0627\u0644\u0634\u0631\u0628 \u0648\u0627\u0644\u0635\u0631\u0641 \u0627\u0644\u0635\u062d\u064a.\n\u0627\u0644\u062e\u062f\u0645\u0627\u062a \u0627\u0644\u0645\u062d\u0644\u064a\u0629 \u0648\u062a\u062d\u0633\u064a\u0646 \u0627\u0644\u0628\u064a\u0626\u0629.","\u0627\u0644\u0637\u0627\u0642\u0629 \u0648\u0627\u0644\u0643\u0647\u0631\u0628\u0627\u0621\u060c \u0627\u0644\u0646\u0642\u0644 \u0648\u0627\u0644\u0637\u0631\u0642\u060c \u0627\u0644\u0625\u0633\u0643\u0627\u0646\u060c \u0645\u064a\u0627\u0647 \u0627\u0644\u0634\u0631\u0628 \u0648\u0627\u0644\u0635\u0631\u0641 \u0627\u0644\u0635\u062d\u064a\u060c \u0627\u0644\u0631\u064a \u0648\u0627\u0644\u0632\u0631\u0627\u0639\u0629\u060c \u0627\u0644\u0628\u064a\u0626\u0629 \u0648\u0627\u0644\u062e\u062f\u0645\u0627\u062a \u0627\u0644\u0645\u062d\u0644\u064a\u0629.","6 \u0645\u0634\u0631\u0648\u0639\u0627\u062a \u0641\u064a \u0642\u0637\u0627\u0639 \u0627\u0644\u0646\u0642\u0644 \u0628\u0627\u0633\u062a\u062b\u0645\u0627\u0631\u0627\u062a 4.7 \u0645\u0644\u064a\u0627\u0631 \u062c\u0646\u064a\u0647.\n\n\u0627\u0633\u062a\u0643\u0645\u0627\u0644 \u062a\u0637\u0648\u064a\u0631 \u0627\u0644\u0637\u0631\u064a\u0642 \u0627\u0644\u0633\u0627\u062d\u0644\u064a \u0627\u0644\u062f\u0648\u0644\u064a.\n\n\u0627\u0633\u062a\u0643\u0645\u0627\u0644 \u0627\u0632\u062f\u0648\u0627\u062c \u0637\u0631\u064a\u0642 \u0645\u0637\u0631\u0648\u062d / \u0633\u064a\u0648\u0629.\n\n28 \u0645\u0634\u0631\u0648\u0639\u0627\u064b \u0644\u0645\u064a\u0627\u0647 \u0627\u0644\u0634\u0631\u0628 \u0648\u0627\u0644\u0635\u0631\u0641 \u0627\u0644\u0635\u062d\u064a \u0628\u0627\u0639\u062a\u0645\u0627\u062f\u0627\u062a 652 \u0645\u0644\u064a\u0648\u0646 \u062c\u0646\u064a\u0647.\n\n\u0627\u0633\u062a\u0643\u0645\u0627\u0644 \u0645\u062d\u0637\u0629 \u0627\u0644\u0645\u0639\u0627\u0644\u062c\u0629 \u0627\u0644\u062b\u0644\u0627\u062b\u064a\u0629 \u0628\u0637\u0627\u0642\u0629 60 \u0623\u0644\u0641 \u0645\u062a\u0631 \u0645\u0643\u0639\u0628 \u064a\u0648\u0645\u064a\u0627\u064b.\n\n\u0627\u0633\u062a\u0643\u0645\u0627\u0644 \u0645\u062d\u0637\u0629 \u062a\u062d\u0644\u064a\u0629 \u0645\u064a\u0627\u0647 \u0627\u0644\u0628\u062d\u0631 \u0628\u0645\u062f\u064a\u0646\u0629 \u0627\u0644\u0633\u0644\u0648\u0645 \u0628\u0637\u0627\u0642\u0629 5 \u0622\u0644\u0627\u0641 \u0645\u062a\u0631 \u0645\u0643\u0639\u0628 \u064a\u0648\u0645\u064a\u0627\u064b.\n\n4 \u0645\u0634\u0631\u0648\u0639\u0627\u062a \u0644\u0644\u0631\u064a \u0648\u0627\u0644\u0632\u0631\u0627\u0639\u0629 \u0628\u0627\u0639\u062a\u0645\u0627\u062f\u0627\u062a 543 \u0645\u0644\u064a\u0648\u0646 \u062c\u0646\u064a\u0647.\n\n89 \u0645\u0634\u0631\u0648\u0639\u0627\u064b \u0644\u0644\u0628\u064a\u0626\u0629 \u0648\u0627\u0644\u062e\u062f\u0645\u0627\u062a \u0627\u0644\u0645\u062d\u0644\u064a\u0629 \u0628\u0627\u0633\u062a\u062b\u0645\u0627\u0631\u0627\u062a 632 \u0645\u0644\u064a\u0648\u0646 \u062c\u0646\u064a\u0647.","\u0645\u062d\u0627\u0641\u0638\u0629 \u0648\u0627\u0633\u0639\u0629 \u0627\u0644\u0645\u0633\u0627\u062d\u0629 \u0639\u0644\u0649 \u0627\u0644\u0633\u0627\u062d\u0644 \u0627\u0644\u0634\u0645\u0627\u0644\u064a \u0627\u0644\u063a\u0631\u0628\u064a \u0648\u062a\u0636\u0645 \u0639\u062f\u062f\u0627\u064b \u0645\u0646 \u0627\u0644\u0645\u062f\u0646 \u0627\u0644\u0633\u064a\u0627\u062d\u064a\u0629.",u.X)
B.HL=new A.bO("\u062f\u0645\u064a\u0627\u0637","\u064a\u0633\u062a\u0647\u062f\u0641 \u0627\u0644\u0645\u062e\u0637\u0637 \u062a\u0646\u0641\u064a\u0630 \u0648\u0645\u062a\u0627\u0628\u0639\u0629 180 \u0645\u0634\u0631\u0648\u0639\u0627\u064b \u062a\u0646\u0645\u0648\u064a\u0627\u064b \u062a\u063a\u0637\u064a \u0645\u0631\u0627\u0643\u0632 \u0648\u0642\u0631\u0649 \u0627\u0644\u0645\u062d\u0627\u0641\u0638\u0629.","\u0627\u0644\u0646\u0642\u0644: 43.5% \u0628\u0642\u064a\u0645\u0629 3.1 \u0645\u0644\u064a\u0627\u0631 \u062c\u0646\u064a\u0647.\n\u0627\u0644\u0625\u0633\u0643\u0627\u0646 \u0648\u0645\u064a\u0627\u0647 \u0627\u0644\u0634\u0631\u0628 \u0648\u0627\u0644\u0635\u0631\u0641 \u0627\u0644\u0635\u062d\u064a: 11.5% \u0628\u0646\u062d\u0648 828.6 \u0645\u0644\u064a\u0648\u0646 \u062c\u0646\u064a\u0647.\n\u0627\u0644\u062a\u0646\u0645\u064a\u0629 \u0627\u0644\u0645\u062d\u0644\u064a\u0629: 9% \u0628\u0646\u062d\u0648 674.5 \u0645\u0644\u064a\u0648\u0646 \u062c\u0646\u064a\u0647.\n\u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0642\u0628\u0644 \u0627\u0644\u062c\u0627\u0645\u0639\u064a: 431 \u0645\u0644\u064a\u0648\u0646 \u062c\u0646\u064a\u0647.\n\u0627\u0644\u0635\u062d\u0629 \u0648\u0627\u0644\u0642\u0637\u0627\u0639\u0627\u062a \u0627\u0644\u0623\u062e\u0631\u0649: \u0648\u0641\u0642 \u0627\u0644\u0627\u062d\u062a\u064a\u0627\u062c\u0627\u062a \u0627\u0644\u0645\u062d\u0644\u064a\u0629.","\u0627\u0644\u0646\u0642\u0644 \u0648\u0627\u0644\u0637\u0631\u0642\u060c \u0627\u0644\u0625\u0633\u0643\u0627\u0646 \u0648\u0627\u0644\u0645\u0631\u0627\u0641\u0642\u060c \u0627\u0644\u062a\u0646\u0645\u064a\u0629 \u0627\u0644\u0645\u062d\u0644\u064a\u0629\u060c \u0627\u0644\u062a\u0639\u0644\u064a\u0645\u060c \u0627\u0644\u0635\u062d\u0629\u060c \u0627\u0644\u0643\u0647\u0631\u0628\u0627\u0621\u060c \u0627\u0644\u0628\u064a\u0626\u0629.","\u062a\u0637\u0648\u064a\u0631 \u0627\u0644\u0645\u062d\u0627\u0648\u0631 \u0627\u0644\u0645\u0631\u0648\u0631\u064a\u0629 \u0627\u0644\u0645\u0624\u062f\u064a\u0629 \u0625\u0644\u0649 \u0645\u064a\u0646\u0627\u0621 \u062f\u0645\u064a\u0627\u0637 \u0648\u0645\u062f\u064a\u0646\u0629 \u062f\u0645\u064a\u0627\u0637 \u0644\u0644\u0623\u062b\u0627\u062b.\n\n\u062a\u0637\u0648\u064a\u0631 \u0634\u0628\u0643\u0627\u062a \u0627\u0644\u0637\u0631\u0642 \u0627\u0644\u062f\u0627\u062e\u0644\u064a\u0629 \u0628\u064a\u0646 \u062f\u0645\u064a\u0627\u0637 \u0648\u0641\u0627\u0631\u0633\u0643\u0648\u0631 \u0648\u0643\u0641\u0631 \u0633\u0639\u062f \u0648\u0627\u0644\u0632\u0631\u0642\u0627 \u0648\u0643\u0641\u0631 \u0627\u0644\u0628\u0637\u064a\u062e.\n\n14 \u0645\u0634\u0631\u0648\u0639\u0627\u064b \u0641\u064a \u0642\u0637\u0627\u0639 \u0627\u0644\u0635\u062d\u0629 \u062a\u0634\u0645\u0644 \u0645\u0633\u062a\u0634\u0641\u0649 \u0641\u0627\u0631\u0633\u0643\u0648\u0631 \u0627\u0644\u0645\u0631\u0643\u0632\u064a \u0648\u0645\u0633\u062a\u0634\u0641\u0649 \u0623\u0648\u0631\u0627\u0645 \u062f\u0645\u064a\u0627\u0637 \u0648\u0645\u0633\u062a\u0634\u0641\u0649 \u0642\u0644\u0628 \u062f\u0645\u064a\u0627\u0637 \u0648\u0645\u0631\u0643\u0632 \u062a\u062c\u0645\u064a\u0639 \u0627\u0644\u0628\u0644\u0627\u0632\u0645\u0627.\n\n32 \u0645\u0634\u0631\u0648\u0639\u0627\u064b \u0644\u0644\u062a\u0646\u0645\u064a\u0629 \u0627\u0644\u0645\u062d\u0644\u064a\u0629 \u062a\u0634\u0645\u0644 \u0627\u0644\u0643\u0647\u0631\u0628\u0627\u0621 \u0648\u0627\u0644\u0625\u0646\u0627\u0631\u0629 \u0648\u0627\u0644\u062d\u0645\u0627\u064a\u0629 \u0627\u0644\u0645\u062f\u0646\u064a\u0629 \u0648\u062a\u062d\u0633\u064a\u0646 \u0627\u0644\u0628\u064a\u0626\u0629.\n\n\u0625\u0646\u0634\u0627\u0621 \u0648\u0625\u062d\u0644\u0627\u0644 \u0648\u062a\u0637\u0648\u064a\u0631 414 \u0641\u0635\u0644\u0627\u064b \u062f\u0631\u0627\u0633\u064a\u0627\u064b.","\u0645\u062d\u0627\u0641\u0638\u0629 \u0633\u0627\u062d\u0644\u064a\u0629 \u0645\u0639\u0631\u0648\u0641\u0629 \u0628\u0627\u0644\u0646\u0634\u0627\u0637 \u0627\u0644\u0635\u0646\u0627\u0639\u064a \u0648\u0627\u0644\u062a\u062c\u0627\u0631\u064a \u0648\u062e\u0627\u0635\u0629 \u0635\u0646\u0627\u0639\u0629 \u0627\u0644\u0623\u062b\u0627\u062b.",u.X)
B.HN=new A.bO("\u0627\u0644\u062f\u0642\u0647\u0644\u064a\u0629","\u064a\u0633\u062a\u0647\u062f\u0641 \u0627\u0644\u0645\u062e\u0637\u0637 \u062a\u0646\u0641\u064a\u0630 \u0648\u0645\u062a\u0627\u0628\u0639\u0629 582 \u0645\u0634\u0631\u0648\u0639\u0627\u064b \u062a\u0646\u0645\u0648\u064a\u0627\u064b\u060c \u0628\u0627\u0644\u0625\u0636\u0627\u0641\u0629 \u0625\u0644\u0649 \u0645\u0634\u0631\u0648\u0639\u0627\u062a \u062d\u064a\u0627\u0629 \u0643\u0631\u064a\u0645\u0629 \u0641\u064a \u0645\u0631\u0643\u0632 \u0634\u0631\u0628\u064a\u0646 \u0648\u0627\u0644\u062a\u064a \u062a\u0633\u062a\u0647\u062f\u0641 26 \u0642\u0631\u064a\u0629 \u0644\u062e\u062f\u0645\u0629 \u0646\u062d\u0648 380 \u0623\u0644\u0641 \u0646\u0633\u0645\u0629.","\u0627\u0644\u0646\u0642\u0644 \u0648\u0627\u0644\u0637\u0631\u0642: \u0646\u062d\u0648 25%.\n\u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u0639\u0627\u0644\u064a \u0648\u0627\u0644\u0628\u062d\u062b \u0627\u0644\u0639\u0644\u0645\u064a: 21%.\n\u0627\u0644\u0625\u0633\u0643\u0627\u0646 \u0648\u0645\u064a\u0627\u0647 \u0627\u0644\u0634\u0631\u0628 \u0648\u0627\u0644\u0635\u0631\u0641 \u0627\u0644\u0635\u062d\u064a: 13%.\n\u0627\u0644\u062a\u0646\u0645\u064a\u0629 \u0627\u0644\u0645\u062d\u0644\u064a\u0629: 10%.\n\u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0642\u0628\u0644 \u0627\u0644\u062c\u0627\u0645\u0639\u064a: 9%.\n\u0627\u0644\u0635\u062d\u0629 \u0648\u0627\u0644\u0642\u0637\u0627\u0639\u0627\u062a \u0627\u0644\u0623\u062e\u0631\u0649: \u0627\u0644\u0646\u0633\u0628\u0629 \u0627\u0644\u0645\u062a\u0628\u0642\u064a\u0629.","\u0627\u0644\u0646\u0642\u0644 \u0648\u0627\u0644\u0637\u0631\u0642\u060c \u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u0639\u0627\u0644\u064a\u060c \u0627\u0644\u0625\u0633\u0643\u0627\u0646 \u0648\u0627\u0644\u0645\u0631\u0627\u0641\u0642\u060c \u0627\u0644\u062a\u0646\u0645\u064a\u0629 \u0627\u0644\u0645\u062d\u0644\u064a\u0629\u060c \u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0642\u0628\u0644 \u0627\u0644\u062c\u0627\u0645\u0639\u064a\u060c \u0627\u0644\u0635\u062d\u0629.","\u062a\u0637\u0648\u064a\u0631 \u0627\u0644\u0637\u0631\u0642 \u0627\u0644\u0625\u0642\u0644\u064a\u0645\u064a\u0629 \u0648\u0627\u0644\u062f\u0627\u062e\u0644\u064a\u0629 \u0628\u064a\u0646 \u0627\u0644\u0645\u0646\u0635\u0648\u0631\u0629 \u0648\u0645\u064a\u062a \u063a\u0645\u0631 \u0648\u0627\u0644\u0633\u0646\u0628\u0644\u0627\u0648\u064a\u0646 \u0648\u062f\u0643\u0631\u0646\u0633 \u0648\u0637\u0644\u062e\u0627.\n\n\u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0644\u0625\u062d\u0644\u0627\u0644 \u0648\u062a\u062c\u062f\u064a\u062f \u0643\u0648\u0628\u0631\u064a \u0627\u0644\u0631\u062d\u0645\u0627\u0646\u064a\u0629 \u0628\u0645\u0631\u0643\u0632 \u0645\u064a\u062a \u063a\u0645\u0631.\n\n\u062a\u062d\u062f\u064a\u062b \u0645\u0639\u062f\u0627\u062a \u0627\u0644\u062d\u0645\u0644\u0627\u062a \u0627\u0644\u0645\u064a\u0643\u0627\u0646\u064a\u0643\u064a\u0629 \u0648\u0645\u0646\u0638\u0648\u0645\u0629 \u0627\u0644\u0646\u0638\u0627\u0641\u0629.\n\n\u062a\u062f\u0639\u064a\u0645 \u0634\u0628\u0643\u0627\u062a \u0627\u0644\u0643\u0647\u0631\u0628\u0627\u0621 \u0648\u0627\u0644\u0625\u0646\u0627\u0631\u0629.\n\n\u0645\u0634\u0631\u0648\u0639\u0627\u062a \u0627\u0644\u0635\u0631\u0641 \u0627\u0644\u0635\u062d\u064a \u0648\u0645\u062d\u0637\u0627\u062a \u0627\u0644\u0645\u0639\u0627\u0644\u062c\u0629.\n\n\u0645\u0634\u0631\u0648\u0639\u0627\u062a \u062d\u064a\u0627\u0629 \u0643\u0631\u064a\u0645\u0629 \u0628\u0642\u0631\u0649 \u0634\u0631\u0628\u064a\u0646 \u062a\u0634\u0645\u0644 \u0627\u0644\u0623\u0644\u064a\u0627\u0641 \u0627\u0644\u0636\u0648\u0626\u064a\u0629 \u0648\u0645\u062c\u0645\u0639\u0627\u062a \u0627\u0644\u062e\u062f\u0645\u0627\u062a \u0648\u0627\u0644\u0645\u062f\u0627\u0631\u0633 \u0648\u0645\u0631\u0627\u0643\u0632 \u0627\u0644\u0634\u0628\u0627\u0628.","\u0645\u062d\u0627\u0641\u0638\u0629 \u0631\u0626\u064a\u0633\u064a\u0629 \u0641\u064a \u062f\u0644\u062a\u0627 \u0627\u0644\u0646\u064a\u0644 \u0630\u0627\u062a \u0643\u062b\u0627\u0641\u0629 \u0633\u0643\u0627\u0646\u064a\u0629 \u0648\u0646\u0634\u0627\u0637 \u0632\u0631\u0627\u0639\u064a \u0648\u062e\u062f\u0645\u064a \u0643\u0628\u064a\u0631.",u.X)
B.HD=new A.bO("\u0627\u0644\u0634\u0631\u0642\u064a\u0629","\u064a\u0633\u062a\u0647\u062f\u0641 \u0627\u0644\u0645\u062e\u0637\u0637 \u062a\u0646\u0641\u064a\u0630 \u0648\u0645\u062a\u0627\u0628\u0639\u0629 472 \u0645\u0634\u0631\u0648\u0639\u0627\u064b \u062a\u0646\u0645\u0648\u064a\u0627\u064b \u062a\u063a\u0637\u064a \u0645\u0631\u0627\u0643\u0632 \u0648\u0645\u062f\u0646 \u0648\u0642\u0631\u0649 \u0627\u0644\u0645\u062d\u0627\u0641\u0638\u0629.","\u0627\u0644\u0625\u0633\u0643\u0627\u0646 \u0648\u0645\u064a\u0627\u0647 \u0627\u0644\u0634\u0631\u0628 \u0648\u0627\u0644\u0635\u0631\u0641 \u0627\u0644\u0635\u062d\u064a: 6.5 \u0645\u0644\u064a\u0627\u0631 \u062c\u0646\u064a\u0647.\n\u0627\u0644\u0646\u0642\u0644 \u0648\u0627\u0644\u0637\u0631\u0642 \u0645\u0646 \u0627\u0644\u0623\u0648\u0644\u0648\u064a\u0627\u062a \u0627\u0644\u0631\u0626\u064a\u0633\u064a\u0629.\n\u0627\u0644\u062a\u0646\u0645\u064a\u0629 \u0627\u0644\u0645\u062d\u0644\u064a\u0629 \u0644\u062a\u062d\u0633\u064a\u0646 \u0627\u0644\u0628\u064a\u0626\u0629 \u0648\u0627\u0644\u0637\u0631\u0642 \u0648\u0627\u0644\u0625\u0646\u0627\u0631\u0629.\n\u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0642\u0628\u0644 \u0627\u0644\u062c\u0627\u0645\u0639\u064a \u0648\u0627\u0644\u062c\u0627\u0645\u0639\u064a.\n\u0627\u0644\u0635\u062d\u0629 \u0648\u0631\u0641\u0639 \u0643\u0641\u0627\u0621\u0629 \u0627\u0644\u0645\u0633\u062a\u0634\u0641\u064a\u0627\u062a.","\u0627\u0644\u0625\u0633\u0643\u0627\u0646 \u0648\u0627\u0644\u0645\u0631\u0627\u0641\u0642\u060c \u0627\u0644\u0646\u0642\u0644 \u0648\u0627\u0644\u0637\u0631\u0642\u060c \u0627\u0644\u062a\u0646\u0645\u064a\u0629 \u0627\u0644\u0645\u062d\u0644\u064a\u0629\u060c \u0627\u0644\u062a\u0639\u0644\u064a\u0645\u060c \u0627\u0644\u0635\u062d\u0629\u060c \u0627\u0644\u0643\u0647\u0631\u0628\u0627\u0621\u060c \u0627\u0644\u0628\u064a\u0626\u0629.","122 \u0645\u0634\u0631\u0648\u0639\u0627\u064b \u0641\u064a \u0627\u0644\u0625\u0633\u0643\u0627\u0646 \u0648\u0627\u0644\u0645\u0631\u0627\u0641\u0642.\n\n\u0645\u0634\u0631\u0648\u0639\u0627\u062a \u0627\u0644\u0625\u0633\u0643\u0627\u0646 \u0627\u0644\u0627\u062c\u062a\u0645\u0627\u0639\u064a \u0628\u062a\u0643\u0644\u0641\u0629 3.6 \u0645\u0644\u064a\u0627\u0631 \u062c\u0646\u064a\u0647.\n\n\u0627\u0633\u062a\u0643\u0645\u0627\u0644 \u0645\u062d\u0637\u0629 \u0631\u0641\u0639 \u0627\u0644\u0635\u0631\u0641 \u0627\u0644\u0635\u062d\u064a \u0628\u0645\u062f\u064a\u0646\u0629 \u0627\u0644\u0639\u0627\u0634\u0631 \u0645\u0646 \u0631\u0645\u0636\u0627\u0646.\n\n\u0627\u0633\u062a\u0643\u0645\u0627\u0644 \u0645\u062d\u0637\u0629 \u062a\u0646\u0642\u064a\u0629 \u0645\u064a\u0627\u0647 \u0627\u0644\u0634\u0631\u0628 \u0628\u0637\u0627\u0642\u0629 600 \u0623\u0644\u0641 \u0645\u062a\u0631 \u0645\u0643\u0639\u0628 \u064a\u0648\u0645\u064a\u0627\u064b.\n\n\u0645\u0634\u0631\u0648\u0639\u0627\u062a \u0627\u0644\u0637\u0631\u0642 \u0641\u064a \u0623\u0628\u0648 \u062d\u0645\u0627\u062f \u0648\u0647\u0647\u064a\u0627 \u0648\u0623\u0648\u0644\u0627\u062f \u0635\u0642\u0631.\n\n181 \u0645\u0634\u0631\u0648\u0639 \u0635\u0631\u0641 \u0635\u062d\u064a \u0648102 \u0645\u0634\u0631\u0648\u0639 \u0645\u064a\u0627\u0647 \u0634\u0631\u0628 \u0636\u0645\u0646 \u062d\u064a\u0627\u0629 \u0643\u0631\u064a\u0645\u0629.\n\n\u0625\u0646\u0634\u0627\u0621 10 \u0645\u062c\u0645\u0639\u0627\u062a \u062d\u0643\u0648\u0645\u064a\u0629 \u064810 \u0645\u062c\u0645\u0639\u0627\u062a \u0632\u0631\u0627\u0639\u064a\u0629 \u062e\u062f\u0645\u064a\u0629 \u0628\u0642\u0631\u0649 \u0645\u0631\u0643\u0632 \u0627\u0644\u062d\u0633\u064a\u0646\u064a\u0629.","\u0645\u0646 \u0623\u0643\u0628\u0631 \u0645\u062d\u0627\u0641\u0638\u0627\u062a \u0627\u0644\u062f\u0644\u062a\u0627 \u0633\u0643\u0627\u0646\u0627\u064b \u0648\u062a\u0636\u0645 \u0646\u0634\u0627\u0637\u0627\u064b \u0632\u0631\u0627\u0639\u064a\u0627\u064b \u0648\u0635\u0646\u0627\u0639\u064a\u0627\u064b \u0648\u0627\u0633\u0639\u0627\u064b.",u.X)
B.Hv=new A.bO("\u0628\u0648\u0631\u0633\u0639\u064a\u062f","\u062a\u0636\u0645 \u0627\u0644\u0645\u062d\u0627\u0641\u0638\u0629 \u0645\u0634\u0631\u0648\u0639\u0627\u062a \u062a\u0646\u0645\u0648\u064a\u0629 \u0648\u062e\u062f\u0645\u064a\u0629 \u0645\u062a\u0639\u062f\u062f\u0629 \u0636\u0645\u0646 \u0645\u0634\u0631\u0648\u0639\u0627\u062a \u0627\u0644\u0628\u0646\u064a\u0629 \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629 \u0648\u0627\u0644\u062e\u062f\u0645\u0627\u062a.","\u062a\u062a\u0648\u0632\u0639 \u0627\u0644\u0627\u0633\u062a\u062b\u0645\u0627\u0631\u0627\u062a \u0648\u0627\u0644\u0645\u0634\u0631\u0648\u0639\u0627\u062a \u0639\u0644\u0649 \u0642\u0637\u0627\u0639\u0627\u062a \u0627\u0644\u0628\u0646\u064a\u0629 \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629 \u0648\u0627\u0644\u062e\u062f\u0645\u0627\u062a \u0627\u0644\u0639\u0627\u0645\u0629.","\u0627\u0644\u0635\u062d\u0629\u060c \u0627\u0644\u062a\u0639\u0644\u064a\u0645\u060c \u0627\u0644\u0637\u0631\u0642\u060c \u0645\u064a\u0627\u0647 \u0627\u0644\u0634\u0631\u0628 \u0648\u0627\u0644\u0635\u0631\u0641 \u0627\u0644\u0635\u062d\u064a\u060c \u0627\u0644\u0625\u0633\u0643\u0627\u0646\u060c \u0627\u0644\u062e\u062f\u0645\u0627\u062a \u0627\u0644\u062d\u0643\u0648\u0645\u064a\u0629.","\u0645\u0634\u0631\u0648\u0639\u0627\u062a \u0641\u064a \u0627\u0644\u0628\u0646\u064a\u0629 \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629 \u0648\u0627\u0644\u062e\u062f\u0645\u0627\u062a\u060c \u0645\u0639 \u0627\u0633\u062a\u0645\u0631\u0627\u0631 \u062a\u0646\u0641\u064a\u0630 \u0648\u062a\u0637\u0648\u064a\u0631 \u0639\u062f\u062f \u0645\u0646 \u0627\u0644\u0645\u0634\u0631\u0648\u0639\u0627\u062a \u0627\u0644\u062e\u062f\u0645\u064a\u0629.","\u0645\u062d\u0627\u0641\u0638\u0629 \u0633\u0627\u062d\u0644\u064a\u0629 \u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u062a\u0642\u0639 \u0639\u0646\u062f \u0627\u0644\u0645\u062f\u062e\u0644 \u0627\u0644\u0634\u0645\u0627\u0644\u064a \u0644\u0642\u0646\u0627\u0629 \u0627\u0644\u0633\u0648\u064a\u0633.",u.h)
B.HJ=new A.bO("\u0627\u0644\u0625\u0633\u0645\u0627\u0639\u064a\u0644\u064a\u0629","\u062a\u0636\u0645 \u0627\u0644\u0645\u062d\u0627\u0641\u0638\u0629 \u0645\u0634\u0631\u0648\u0639\u0627\u062a \u0645\u062a\u0639\u062f\u062f\u0629\u060c \u0645\u0646 \u0628\u064a\u0646\u0647\u0627 \u0645\u0634\u0631\u0648\u0639\u0627\u062a \u0645\u0631\u062a\u0628\u0637\u0629 \u0628\u0645\u0628\u0627\u062f\u0631\u0629 \u062d\u064a\u0627\u0629 \u0643\u0631\u064a\u0645\u0629.","\u062a\u062a\u0648\u0632\u0639 \u0627\u0644\u0645\u0634\u0631\u0648\u0639\u0627\u062a \u0639\u0644\u0649 \u0642\u0637\u0627\u0639\u0627\u062a \u0627\u0644\u062e\u062f\u0645\u0627\u062a \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629 \u0648\u0627\u0644\u0628\u0646\u064a\u0629 \u0627\u0644\u062a\u062d\u062a\u064a\u0629.","\u0645\u064a\u0627\u0647 \u0627\u0644\u0634\u0631\u0628\u060c \u0627\u0644\u0635\u0631\u0641 \u0627\u0644\u0635\u062d\u064a\u060c \u0627\u0644\u062a\u0639\u0644\u064a\u0645\u060c \u0627\u0644\u0635\u062d\u0629\u060c \u0627\u0644\u0637\u0631\u0642\u060c \u0627\u0644\u062e\u062f\u0645\u0627\u062a \u0627\u0644\u0632\u0631\u0627\u0639\u064a\u0629\u060c \u0627\u0644\u0634\u0628\u0627\u0628 \u0648\u0627\u0644\u0631\u064a\u0627\u0636\u0629.","\u062a\u0646\u0641\u064a\u0630 \u0639\u062f\u062f \u0645\u0646 \u0645\u062d\u0637\u0627\u062a \u0627\u0644\u0645\u064a\u0627\u0647 \u0648\u0627\u0644\u0645\u0639\u0627\u0644\u062c\u0629 \u0648\u0631\u0627\u0641\u0639\u0640\u0627\u062a \u0627\u0644\u0635\u0631\u0641\u060c \u0625\u0644\u0649 \u062c\u0627\u0646\u0628 \u0645\u0634\u0631\u0648\u0639\u0627\u062a \u0623\u062e\u0631\u0649 \u062c\u0627\u0631\u064a\u0629 \u0641\u064a \u0627\u0644\u0642\u0637\u0627\u0639\u0627\u062a \u0627\u0644\u062e\u062f\u0645\u064a\u0629.","\u0645\u062d\u0627\u0641\u0638\u0629 \u0645\u0647\u0645\u0629 \u0641\u064a \u0645\u0646\u0637\u0642\u0629 \u0642\u0646\u0627\u0629 \u0627\u0644\u0633\u0648\u064a\u0633 \u0648\u062a\u062a\u0645\u064a\u0632 \u0628\u0645\u0648\u0642\u0639 \u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a.",u.h)
B.Hr=new A.bO("\u0627\u0644\u0633\u0648\u064a\u0633","\u062a\u062a\u0636\u0645\u0646 \u0627\u0644\u062e\u0637\u0629 \u0645\u0634\u0631\u0648\u0639\u0627\u062a \u062a\u0646\u0645\u0648\u064a\u0629 \u0648\u062e\u062f\u0645\u064a\u0629 \u0641\u064a \u0642\u0637\u0627\u0639\u0627\u062a \u0627\u0644\u0628\u0646\u064a\u0629 \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629 \u0648\u0627\u0644\u062e\u062f\u0645\u0627\u062a \u0627\u0644\u0639\u0627\u0645\u0629.","\u062a\u062a\u0648\u0632\u0639 \u0627\u0644\u0645\u0634\u0631\u0648\u0639\u0627\u062a \u0639\u0644\u0649 \u0642\u0637\u0627\u0639\u0627\u062a \u0627\u0644\u0628\u0646\u064a\u0629 \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629 \u0648\u0627\u0644\u062e\u062f\u0645\u0627\u062a \u0627\u0644\u0639\u0627\u0645\u0629.","\u0627\u0644\u0635\u062d\u0629\u060c \u0627\u0644\u062a\u0639\u0644\u064a\u0645\u060c \u0627\u0644\u0637\u0631\u0642\u060c \u0645\u064a\u0627\u0647 \u0627\u0644\u0634\u0631\u0628 \u0648\u0627\u0644\u0635\u0631\u0641 \u0627\u0644\u0635\u062d\u064a\u060c \u0627\u0644\u0625\u0633\u0643\u0627\u0646\u060c \u0627\u0644\u062e\u062f\u0645\u0627\u062a.","\u0645\u0634\u0631\u0648\u0639\u0627\u062a \u062e\u062f\u0645\u064a\u0629 \u0648\u062a\u0646\u0645\u0648\u064a\u0629 \u0641\u064a \u0627\u0644\u0628\u0646\u064a\u0629 \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629 \u0648\u0627\u0644\u062e\u062f\u0645\u0627\u062a \u0627\u0644\u0639\u0627\u0645\u0629.","\u0645\u062d\u0627\u0641\u0638\u0629 \u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0639\u0646\u062f \u0627\u0644\u0645\u062f\u062e\u0644 \u0627\u0644\u062c\u0646\u0648\u0628\u064a \u0644\u0642\u0646\u0627\u0629 \u0627\u0644\u0633\u0648\u064a\u0633 \u0648\u062a\u0636\u0645 \u0645\u0648\u0627\u0646\u0626 \u0648\u0623\u0646\u0634\u0637\u0629 \u0635\u0646\u0627\u0639\u064a\u0629 \u0645\u0647\u0645\u0629.",u.h)
B.HF=new A.bO("\u0643\u0641\u0631 \u0627\u0644\u0634\u064a\u062e","698 \u0645\u0634\u0631\u0648\u0639\u0627\u064b \u0641\u064a \u0645\u0631\u0643\u0632 \u0645\u0637\u0648\u0628\u0633 \u0636\u0645\u0646 \u0645\u0628\u0627\u062f\u0631\u0629 \u062d\u064a\u0627\u0629 \u0643\u0631\u064a\u0645\u0629.","\u062a\u062a\u0648\u0632\u0639 \u0627\u0644\u0645\u0634\u0631\u0648\u0639\u0627\u062a \u0648\u0627\u0644\u0627\u0633\u062a\u062b\u0645\u0627\u0631\u0627\u062a \u0639\u0644\u0649 \u0627\u0644\u062e\u062f\u0645\u0627\u062a \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629 \u0648\u0627\u0644\u0628\u0646\u064a\u0629 \u0627\u0644\u062a\u062d\u062a\u064a\u0629 \u0648\u0627\u0644\u062a\u0646\u0645\u064a\u0629 \u0627\u0644\u0645\u062d\u0644\u064a\u0629.","\u0645\u064a\u0627\u0647 \u0627\u0644\u0634\u0631\u0628\u060c \u0627\u0644\u0635\u0631\u0641 \u0627\u0644\u0635\u062d\u064a\u060c \u0627\u0644\u062a\u0639\u0644\u064a\u0645\u060c \u0627\u0644\u0635\u062d\u0629\u060c \u0627\u0644\u0643\u0647\u0631\u0628\u0627\u0621\u060c \u0627\u0644\u0637\u0631\u0642\u060c \u0627\u0644\u0634\u0628\u0627\u0628 \u0648\u0627\u0644\u0631\u064a\u0627\u0636\u0629\u060c \u0627\u0644\u062e\u062f\u0645\u0627\u062a \u0627\u0644\u0632\u0631\u0627\u0639\u064a\u0629.","\u062a\u0645 \u0627\u0644\u0627\u0646\u062a\u0647\u0627\u0621 \u0645\u0646 \u0639\u062f\u062f \u0643\u0628\u064a\u0631 \u0645\u0646 \u0627\u0644\u0645\u0634\u0631\u0648\u0639\u0627\u062a \u0645\u0639 \u0627\u0633\u062a\u0645\u0631\u0627\u0631 \u062a\u0646\u0641\u064a\u0630 \u0645\u0634\u0631\u0648\u0639\u0627\u062a \u0623\u062e\u0631\u0649 \u0636\u0645\u0646 \u0627\u0644\u0645\u0628\u0627\u062f\u0631\u0629.","\u0645\u062d\u0627\u0641\u0638\u0629 \u0641\u064a \u0634\u0645\u0627\u0644 \u0627\u0644\u062f\u0644\u062a\u0627 \u0648\u062a\u062a\u0645\u064a\u0632 \u0628\u0627\u0644\u0632\u0631\u0627\u0639\u0629 \u0648\u0627\u0644\u062b\u0631\u0648\u0629 \u0627\u0644\u0633\u0645\u0643\u064a\u0629.",u.h)
B.HE=new A.bO("\u0627\u0644\u063a\u0631\u0628\u064a\u0629","\u062a\u0636\u0645 \u0627\u0644\u0645\u062d\u0627\u0641\u0638\u0629 \u0645\u0634\u0631\u0648\u0639\u0627\u062a \u0645\u062a\u0639\u062f\u062f\u0629 \u0636\u0645\u0646 \u0627\u0644\u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u0623\u0648\u0644\u0649 \u0645\u0646 \u0645\u0628\u0627\u062f\u0631\u0629 \u062d\u064a\u0627\u0629 \u0643\u0631\u064a\u0645\u0629.","\u062a\u062a\u0648\u0632\u0639 \u0627\u0644\u0645\u0634\u0631\u0648\u0639\u0627\u062a \u0639\u0644\u0649 \u0642\u0637\u0627\u0639\u0627\u062a \u0627\u0644\u062e\u062f\u0645\u0627\u062a \u0648\u0627\u0644\u0628\u0646\u064a\u0629 \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629.","\u0627\u0644\u0635\u0631\u0641 \u0627\u0644\u0635\u062d\u064a\u060c \u0645\u064a\u0627\u0647 \u0627\u0644\u0634\u0631\u0628\u060c \u0627\u0644\u062a\u0639\u0644\u064a\u0645\u060c \u0627\u0644\u0635\u062d\u0629\u060c \u0627\u0644\u0637\u0631\u0642\u060c \u0627\u0644\u0634\u0628\u0627\u0628 \u0648\u0627\u0644\u0631\u064a\u0627\u0636\u0629\u060c \u0627\u0644\u062e\u062f\u0645\u0627\u062a \u0627\u0644\u0632\u0631\u0627\u0639\u064a\u0629.","\u062a\u0648\u062c\u062f \u0645\u0634\u0631\u0648\u0639\u0627\u062a \u062c\u0627\u0631\u064a\u0629 \u0636\u0645\u0646 \u0627\u0644\u0645\u0628\u0627\u062f\u0631\u0629\u060c \u062e\u0627\u0635\u0629 \u0641\u064a \u0627\u0644\u062e\u062f\u0645\u0627\u062a \u0648\u0627\u0644\u0628\u0646\u064a\u0629 \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629.","\u0645\u062d\u0627\u0641\u0638\u0629 \u062f\u0644\u062a\u0627\u0648\u064a\u0629 \u0630\u0627\u062a \u0643\u062b\u0627\u0641\u0629 \u0633\u0643\u0627\u0646\u064a\u0629 \u0645\u0631\u062a\u0641\u0639\u0629 \u0648\u0646\u0634\u0627\u0637 \u0632\u0631\u0627\u0639\u064a \u0648\u0635\u0646\u0627\u0639\u064a.",u.h)
B.HM=new A.bO("\u0627\u0644\u0645\u0646\u0648\u0641\u064a\u0629","1,606 \u0645\u0634\u0631\u0648\u0639\u0627\u064b \u0641\u064a \u0645\u0631\u0643\u0632\u064a \u0623\u0634\u0645\u0648\u0646 \u0648\u0627\u0644\u0634\u0647\u062f\u0627\u0621.","\u062a\u062a\u0631\u0643\u0632 \u0627\u0644\u0645\u0634\u0631\u0648\u0639\u0627\u062a \u0641\u064a \u0642\u0637\u0627\u0639\u0627\u062a \u0627\u0644\u0628\u0646\u064a\u0629 \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629 \u0648\u0627\u0644\u062e\u062f\u0645\u0627\u062a \u0648\u0627\u0644\u062a\u0646\u0645\u064a\u0629 \u0627\u0644\u0645\u062d\u0644\u064a\u0629.","\u0645\u064a\u0627\u0647 \u0627\u0644\u0634\u0631\u0628\u060c \u0627\u0644\u0635\u0631\u0641 \u0627\u0644\u0635\u062d\u064a\u060c \u0627\u0644\u062a\u0639\u0644\u064a\u0645\u060c \u0627\u0644\u0635\u062d\u0629\u060c \u0627\u0644\u0643\u0647\u0631\u0628\u0627\u0621\u060c \u0627\u0644\u0637\u0631\u0642\u060c \u0627\u0644\u0634\u0628\u0627\u0628 \u0648\u0627\u0644\u0631\u064a\u0627\u0636\u0629\u060c \u0627\u0644\u062e\u062f\u0645\u0627\u062a \u0627\u0644\u0632\u0631\u0627\u0639\u064a\u0629\u060c \u0627\u0644\u062e\u062f\u0645\u0627\u062a \u0627\u0644\u062d\u0643\u0648\u0645\u064a\u0629.","\u0628\u0644\u063a\u062a \u0646\u0633\u0628\u0629 \u0627\u0644\u0625\u0646\u062c\u0627\u0632 \u0641\u064a \u0623\u062d\u062f \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0623\u0643\u062b\u0631 \u0645\u0646 79% \u0645\u0639 \u0627\u0633\u062a\u0645\u0631\u0627\u0631 \u062a\u0646\u0641\u064a\u0630 \u0627\u0644\u0645\u0634\u0631\u0648\u0639\u0627\u062a \u0627\u0644\u0645\u062a\u0628\u0642\u064a\u0629.","\u0645\u062d\u0627\u0641\u0638\u0629 \u062f\u0644\u062a\u0627\u0648\u064a\u0629 \u062a\u062a\u0645\u064a\u0632 \u0628\u0627\u0644\u0643\u062b\u0627\u0641\u0629 \u0627\u0644\u0633\u0643\u0627\u0646\u064a\u0629 \u0648\u0627\u0644\u0646\u0634\u0627\u0637 \u0627\u0644\u0632\u0631\u0627\u0639\u064a \u0648\u0627\u0644\u062e\u062f\u0645\u064a.",u.h)
